// Python-style repr formatting helpers.
// Reproduces how CPython's print() renders lists, tuples, dicts, bools and ints.

export function pyRepr(value) {
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'number') return String(value);
  if (typeof value === 'string') return `'${value}'`;
  if (Array.isArray(value)) return pyList(value);
  if (value instanceof Map) return pyDict(value);
  return String(value);
}

// Python list repr: [1, 2, 3]
export function pyList(items) {
  return `[${items.map(pyRepr).join(', ')}]`;
}

// Python tuple repr: (a, b) — note the trailing comma for 1-tuples
export function pyTuple(items) {
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

// Python dict repr from a Map: {False: [1, 3], True: [2, 4]}
// Map preserves insertion order, matching CPython 3.7+ dict ordering.
export function pyDict(map) {
  const parts = [];
  for (const [k, v] of map) parts.push(`${pyRepr(k)}: ${pyRepr(v)}`);
  return `{${parts.join(', ')}}`;
}

