// Reimplementation of boltons.iterutils.partition and boltons.iterutils.bucketize
// based on observed interface behavior.

// partition(src, key=bool) -> [falsy_list, truthy_list]
// Items where key(item) is falsy go to the first list, truthy to the second.
export function partition(src, key = Boolean) {
  const falsy = [];
  const truthy = [];
  for (const item of src) {
    if (key(item)) truthy.push(item);
    else falsy.push(item);
  }
  return [falsy, truthy];
}

// bucketize(src, key=bool) -> Map of key value -> list of items,
// with keys in order of first occurrence (matches CPython dict ordering).
export function bucketize(src, key = Boolean) {
  const buckets = new Map();
  for (const item of src) {
    const k = key(item);
    if (!buckets.has(k)) buckets.set(k, []);
    buckets.get(k).push(item);
  }
  return buckets;
}

