// Minimal reimplementation of the argparse behavior used by test7.py:
//   parser.add_argument('--a', type=str, required=True, help='Comma-separated numbers')
// Supports: --a VALUE, --a=VALUE, -h/--help, required-argument enforcement,
// unrecognized-argument errors, and exit codes matching argparse (2 on error,
// 0 after --help).

import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test7.mjs');

function usageLine() {
  return `usage: ${PROG} [-h] --a A`;
}

function printHelp() {
  console.log(usageLine());
  console.log('');
  console.log('options:');
  console.log('  -h, --help  show this help message and exit');
  console.log('  --a A       Comma-separated numbers');
}

function error(message) {
  console.error(usageLine());
  console.error(`${PROG}: error: ${message}`);
  process.exit(2);
}

// Parse argv (defaults to process.argv.slice(2)); returns { a: string }.
export function parseArgs(argv = process.argv.slice(2)) {
  let a = null;
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      printHelp();
      process.exit(0);
    } else if (arg === '--a') {
      const next = argv[i + 1];
      if (next === undefined || next.startsWith('-')) {
        error('argument --a: expected one argument');
      }
      a = next;
      i++;
    } else if (arg.startsWith('--a=')) {
      a = arg.slice('--a='.length);
    } else {
      extras.push(arg);
    }
  }

  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }
  if (a === null) {
    error('the following arguments are required: --a');
  }
  return { a };
}

