// Mimics Python's int(str) for base-10 literals: strips surrounding
// whitespace, accepts an optional +/- sign, digits, and single underscores
// between digits. Throws a ValueError-style error otherwise.

export function pyInt(text) {
  const stripped = text.trim();
  if (!/^[+-]?\d+(?:_\d+)*$/.test(stripped)) {
    throw new Error(`invalid literal for int() with base 10: '${text}'`);
  }
  return parseInt(stripped.replace(/_/g, ''), 10);
}

