import { parseArgs } from './lib/argparse.mjs';
import { partition, bucketize } from './lib/iterutils.mjs';
import { pyList, pyTuple, pyDict } from './lib/pyformat.mjs';
import { pyInt } from './lib/pyint.mjs';

const args = parseArgs();

const numbers = args.a.split(',').map((x) => pyInt(x));

// Partition into evens and odds
const result1 = partition(numbers, (x) => x % 2 === 0);
console.log(pyTuple(result1.map(pyList)));

// Partition into positives and non-positives
const result2 = partition(numbers, (x) => x > 0);
console.log(pyTuple(result2.map(pyList)));

// Bucketize by parity
const result3 = bucketize(numbers, (x) => x % 2 === 0);
console.log(pyDict(result3));

// Bucketize by whether greater than 10
const result4 = bucketize(numbers, (x) => x > 10);
console.log(pyDict(result4));

